begin
   SetFont(0);
   FadeIn;
   SetBkColor(0);
   ClearDevice;
   EndMessage;
   FadeOut;
   setFont(1);
   StaffMessage;
   RGB(6,10,20,63);
   delay(40);
   RGB(6,40,20,0);
   delay(100);
   RGB(6,10,20,63);
   delay(100);
   RGB(6,40,20,0);
   ThunderEffect;
   ClearDevice;
   SetActivePage(page);
   SetVisualPage(page);
   while KeyPressed do c := ReadKey;
   y := 0; c := #255;
   j := 24; i := 1;
   ok := FALSE;
   repeat
      PutImage(600,(y div 20)*20,Font^[47],CopyPut);
      PutImage(600,(y div 20 + 1)*20,Font^[47],CopyPut);
      if y > 350 then y := 0;
      y := y + 2;
      PutSprite(600,y,j);
      if i = 1 then begin
         case j of
            20 : j := 24;
            24 : j := 21;
            21 : begin
                    j := 24;
                    i := 0;
                 end;
         end;
      end
      else begin
         case j of
            20 : begin
                    j := 24;
                    i := 1;
                 end;
            24 : j := 20;
            21 : j := 24;
         end;
      end;
      if KeyPressed then c := ReadKey;
      if c = #27 then ok := TRUE;
      delay(200);
   until ok;
   if AdLibOn then PlayOff;
   UnSound;
   asm
      mov ah,0
      mov al,3
      int $10
      mov ah,1
      mov ch,$20
      int $10
   end;
   FreeMem(font,13776); FreeMem(chara,13776);
   TextColor(7);
   TextBackGround(0);
   ClrScr;
   TextColor(7);
   Writeln(#13);
   RGB(7,0,0,0);
   SetPalette(15,15);
   RGB(15,0,0,0);
   TextColor(15);
   Writeln(#13);
   Writeln('                              << The End >>');
   Writeln('    " The Codex of Another Lore  vol. #1 " is made by Ahn Young-Kie.');
   TextColor(7);
   Writeln('                        You must be a genius !!!');
   for i := 1 to 63 do begin
      RGB(7,i,i,i);
      SetPalette(15,15);
      RGB(15,i,i,i);
      delay(10);
   end;
   delay(500);
   for i := 62 downto 42 do begin
      RGB(7,i,i,i);
      delay(15);
   end;
   asm
      mov ah,1
      mov ch,$13
      mov cl,$14
      int $10
   end;
   Halt;
end

